const TZ = 'Asia/Manila';

// The calendar is queried for the whole day in clinic time.
const day = DateTime.fromISO(String($input.first().json.date ?? ''), { zone: TZ }).startOf('day');
const start = day.isValid ? day : DateTime.now().setZone(TZ).startOf('day');
return [{ json: { timeMin: start.toISO(), timeMax: start.plus({ days: 1 }).toISO() } }];

const TZ = 'Asia/Manila';

// Opening hours per weekday (1 = Monday ... 7 = Sunday), with the lunch break as a gap.
const HOURS = { 1: [[9, 12], [13, 18]], 2: [[9, 12], [13, 18]], 3: [[9, 12], [13, 18]],
                4: [[9, 12], [13, 18]], 5: [[9, 12], [13, 18]], 6: [[9, 12], [13, 18]] };
const STEP_MINUTES = 30;   // a slot can start every 30 minutes
const LEAD_MINUTES = 60;   // no bookings less than an hour from now
const DURATIONS = [[/root canal|whitening/i, 90], [/clean|prophylaxis|filling|extraction/i, 60]];

const req = $('When Executed by Another Workflow').first().json;
const now = req.now ? DateTime.fromISO(req.now, { zone: TZ }) : DateTime.now().setZone(TZ);
const day = DateTime.fromISO(String(req.date ?? ''), { zone: TZ }).startOf('day');
const service = req.service || 'consultation';
const duration = DURATIONS.find(([re]) => re.test(service))?.[1] ?? 30;
const limit = Number(req.limit ?? 5);
const reply = (slots, message) => [{ json: { date: req.date, service, duration_minutes: duration, slots, message } }];

if (!day.isValid) return reply([], 'Invalid date. Use the YYYY-MM-DD format.');
if (day < now.startOf('day')) return reply([], 'That date has already passed.');
const windows = HOURS[day.weekday];
if (!windows) return reply([], 'The clinic is closed on Sundays.');

const busy = $input.all().map((i) => i.json)
  .filter((e) => e.start && e.status !== 'cancelled' && e.transparency !== 'transparent')
  .map((e) => e.start.dateTime
    ? [DateTime.fromISO(e.start.dateTime), DateTime.fromISO(e.end.dateTime)]
    : [DateTime.fromISO(e.start.date, { zone: TZ }), DateTime.fromISO(e.end.date, { zone: TZ })]);

const earliest = now.plus({ minutes: LEAD_MINUTES });
const slots = [];
for (const [open, close] of windows) {
  const closing = day.set({ hour: close });
  for (let t = day.set({ hour: open }); t.plus({ minutes: duration }) <= closing; t = t.plus({ minutes: STEP_MINUTES })) {
    const end = t.plus({ minutes: duration });
    if (t < earliest || busy.some(([s, e]) => t < e && end > s)) continue;
    slots.push({ start: t.toISO(), end: end.toISO(), label: t.setLocale('en-US').toFormat('ccc, LLL d · h:mm a') });
  }
}

const offered = limit > 0 ? slots.slice(0, limit) : slots;
return reply(offered, slots.length ? slots.length + ' open slots that day.' : 'No open slots that day. Try another date.');
